        internal const string AllowMidRunJoinHelp = "SephiriaEnhancements.MultiplayerAccess.AllowMidRunJoin.Help";
        internal const string ReconnectSetting = "SephiriaEnhancements.MultiplayerAccess.ReconnectSupport";
